import sys

def bfs(graph, match, dist):
    queue = []
    for u in range(1, len(graph)):
        if match[u] == -1:
            dist[u] = 0
            queue.append(u)
        else:
            dist[u] = float('inf')

    dist[0] = float('inf')
    while queue:
        u = queue.pop(0)
        if dist[u] < dist[0]:
            for v in graph[u]:
                if dist[match[v]] == float('inf'):
                    dist[match[v]] = dist[u] + 1
                    queue.append(match[v])
    return dist[0] != float('inf')

def dfs(graph, u, match, dist):
    if u == 0:
        return True
    for v in graph[u]:
        if dist[match[v]] == dist[u] + 1 and dfs(graph, match[v], match, dist):
            match[u] = v
            match[v] = u
            return True
    dist[u] = float('inf')
    return False

def max_bipartite_matching(graph, n):
    match = [-1] * (n + 1)
    result = 0
    while bfs(graph, match, [float('inf')] * (n + 1)):
        for u in range(1, n + 1):
            if match[u] == -1 and dfs(graph, u, match, [float('inf')] * (n + 1)):
